// growStack recurses to force the goroutine stack to grow (and therefore to be
// copied), which is what relocates a stack-resident buffer out from under a
// laundered uintptr.
//
//go:noinline
func growStack(n int) int64 {
	if n == 0 {
		return 0
	}
	var pad [512]byte
	pad[0] = byte(n)
	return int64(pad[0]) + growStack(n-1)
}

